import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { getMyFavorites, removeFromFavorites } from '../../services/favoriteService';
import ExcursionCard from '../../components/Card/ExcursionCard';
import './FavoritesPage.css';

const FavoritesPage = () => {
  const [favorites, setFavorites] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadFavorites();
  }, []);

  const loadFavorites = async () => {
    try {
      const data = await getMyFavorites();
      setFavorites(data);
    } catch (e) {
      console.error('Ошибка загрузки избранного', e);
    } finally {
      setLoading(false);
    }
  };

  const handleRemove = async (tourId) => {
    await removeFromFavorites(tourId);
    setFavorites(prev => prev.filter(f => f.tour.id !== tourId));
  };

  if (loading) return <div>Загрузка...</div>;

  return (
    <div className="favorites-page">
      <div className="favorites-container">
        <h1 className="favorites-title">Избранное</h1>

        {favorites.length === 0 ? (
          <div className="favorites-empty">
            <img src="/assets/icons/heart2.svg" alt="Пусто" />
            <h2>В избранном пока пусто</h2>
            <Link to="/catalog">Перейти в каталог</Link>
          </div>
        ) : (
          <div className="favorites-grid">
            {favorites.map(f => (
              <ExcursionCard
                key={f.tour.id}
                excursion={f.tour}
                isFavorite
                onToggleFavorite={() => handleRemove(f.tour.id)}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default FavoritesPage;
